162	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
163	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
164	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
165	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
